import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';
const host=document.querySelector('#pond'), fishLabel=document.querySelector('#fish'), rateLabel=document.querySelector('#rate'), totalLabel=document.querySelector('#total'), shop=document.querySelector('#shop'), ring=document.querySelector('#ring'), toast=document.querySelector('#toast');
const defs=[{id:'pup',name:'Baby otter',icon:'🦦',cost:18,rate:1.2,desc:'A tiny fish finder'},{id:'buddy',name:'Otter buddies',icon:'🦦',cost:110,rate:6,desc:'Double the splashing'},{id:'family',name:'Otter family',icon:'🦦',cost:620,rate:32,desc:'A whole happy raft'},{id:'net',name:'Shiny net',icon:'✨',cost:55,click:2,desc:'More fish per tap'}];
let save;try{save=JSON.parse(localStorage.pondPals||'{}')}catch{save={}};
const game={fish:Math.max(0,save.fish||0),total:Math.max(0,save.total||0),counts:Object.assign({pup:0,buddy:0,family:0,net:0},save.counts||{}),tap:1};
function rate(){return defs.reduce((n,d)=>n+(d.rate||0)*game.counts[d.id],0)}function power(){return 1+game.counts.net*2}
function compact(n){if(n<1000)return Math.floor(n).toLocaleString();const units=['K','M','B','T'];let i=-1;do{n/=1000;i++}while(n>=1000&&i<units.length-1);return n.toFixed(n<10?1:0)+units[i]}
function saveGame(){try{localStorage.pondPals=JSON.stringify({fish:game.fish,total:game.total,counts:game.counts})}catch{}}
function ui(){fishLabel.textContent=compact(game.fish);rateLabel.textContent=compact(rate());totalLabel.textContent=compact(Object.values(game.counts).reduce((a,b)=>a+b,0));for(const d of defs){const btn=document.querySelector('#buy-'+d.id);let price=Math.floor(d.cost*Math.pow(1.16,game.counts[d.id]));btn.querySelector('.price').textContent='🐟 '+compact(price);btn.classList.toggle('afford',game.fish>=price);btn.classList.toggle('locked',game.fish<price);btn.querySelector('.qty').textContent='×'+game.counts[d.id]}}
for(const d of defs){const card=document.createElement('button');card.className='buy-card';card.id='buy-'+d.id;card.innerHTML=`<span class="item-icon">${d.icon}</span><span class="item-info"><b>${d.name}</b><small>${d.desc}</small></span><span class="price">🐟 ${d.cost}</span><span class="qty">×0</span>`;card.addEventListener('click',()=>buy(d));shop.append(card)}
let toastTimer;function message(text){toast.textContent=text;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),1250)}
function buy(d){const price=Math.floor(d.cost*Math.pow(1.16,game.counts[d.id]));if(game.fish<price){message('A few more fish!');return}game.fish-=price;game.counts[d.id]++;if(d.id==='net')message('✨ Shiny net!');else message('🦦 New otter friend!');addOtter();ui();saveGame()}

const scene=new THREE.Scene();scene.background=new THREE.Color('#a9e3d2');scene.fog=new THREE.Fog('#a9e3d2',18,42);
const camera=new THREE.PerspectiveCamera(36,innerWidth/innerHeight,.1,100);camera.position.set(0,8.5,17.5);camera.lookAt(0,0,0);
const renderer=new THREE.WebGLRenderer({antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;host.appendChild(renderer.domElement);
scene.add(new THREE.HemisphereLight('#eaffec','#367b79',2.1));const sun=new THREE.DirectionalLight('#fff2cf',3.3);sun.position.set(-5,12,8);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);scene.add(sun);
const mat=(color,rough=.8)=>new THREE.MeshStandardMaterial({color,roughness:rough,flatShading:true});
const waterMat=new THREE.MeshStandardMaterial({color:'#53bdb3',roughness:.36,metalness:.03,flatShading:true});
const floor=new THREE.Mesh(new THREE.CircleGeometry(22,48),mat('#6fc6a9'));floor.rotation.x=-Math.PI/2;floor.position.y=-1.35;floor.receiveShadow=true;scene.add(floor);
const pond=new THREE.Mesh(new THREE.CircleGeometry(8.7,36),waterMat);pond.rotation.x=-Math.PI/2;pond.position.y=-1.05;pond.receiveShadow=true;scene.add(pond);
const rim=new THREE.Mesh(new THREE.TorusGeometry(8.65,.24,5,52),mat('#f3d695'));rim.rotation.x=Math.PI/2;rim.position.y=-1.02;scene.add(rim);
for(let i=0;i<5;i++){const r=new THREE.Mesh(new THREE.TorusGeometry(1.4+i*.84,.025,4,50),new THREE.MeshStandardMaterial({color:'#d0fff0',transparent:true,opacity:.18,roughness:.3}));r.rotation.x=Math.PI/2;r.position.set((i%2?-.7:.7),-.9-i*.001,0);r.scale.y=.74;scene.add(r)}
// Soft stepping stones and little shoreline plants make the pond feel like a tiny diorama.
for(let i=0;i<19;i++){const a=i/19*Math.PI*2;const rock=new THREE.Mesh(new THREE.DodecahedronGeometry(.42+(i%3)*.1,0),mat(i%2?'#f7d99b':'#f9e8bd'));rock.position.set(Math.cos(a)*9.25,-1.02,Math.sin(a)*7.4);rock.scale.set(1,.52,.78);rock.rotation.y=a;rock.castShadow=true;scene.add(rock)}
const reeds=[];for(let i=0;i<18;i++){const a=i*2.4;const x=Math.cos(a)*(9.8+(i%3)*.6),z=Math.sin(a)*(7.8+(i%4)*.5);const g=new THREE.Group();g.position.set(x,-.95,z);for(let j=0;j<3;j++){const leaf=new THREE.Mesh(new THREE.ConeGeometry(.12,.95+(j%2)*.3,4),mat(j%2?'#479d73':'#67b77c'));leaf.position.set((j-1)*.18,.45,-j*.12);leaf.rotation.z=(j-1)*-.25;g.add(leaf)}scene.add(g);reeds.push(g)}
// Decorative flowers and floating lily pads.
for(let i=0;i<9;i++){let a=i*2.39;const pad=new THREE.Mesh(new THREE.CircleGeometry(.65,7),mat(i%2?'#77cb9c':'#95d59f'));pad.rotation.x=-Math.PI/2;pad.position.set(Math.cos(a)*6.5,-1.005,Math.sin(a)*5.3);pad.scale.set(1,.8,1);scene.add(pad);if(i%3===0){const f=new THREE.Mesh(new THREE.DodecahedronGeometry(.2,0),mat('#ffe7a4'));f.position.set(pad.position.x,.0,pad.position.z);scene.add(f)}}

