for(let i=0;i<9;i++){let a=i*2.39;const pad=new THREE.Mesh(new THREE.CircleGeometry(.65,7),mat(i%2?'#77cb9c':'#95d59f'));pad.rotation.x=-Math.PI/2;pad.position.set(Math.cos(a)*6.5,-1.005,Math.sin(a)*5.3);pad.scale.set(1,.8,1);scene.add(pad);if(i%3===0){const f=new THREE.Mesh(new THREE.DodecahedronGeometry(.2,0),mat('#ffe7a4'));f.position.set(pad.position.x,-.82,pad.position.z);scene.add(f)}}
function ellipsoid(parent,color,pos,scale,geo=new THREE.IcosahedronGeometry(1,1)){const m=new THREE.Mesh(geo,mat(color));m.position.set(...pos);m.scale.set(...scale);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function makeFish(color='#f58a69',scale=1){const g=new THREE.Group();const body=ellipsoid(g,color,[0,0,0],[.9,.52,.39]);const tail=new THREE.Mesh(new THREE.ConeGeometry(.52,.75,3),mat(color));tail.rotation.z=-Math.PI/2;tail.position.x=-.89;tail.scale.set(1,.9,.42);tail.castShadow=true;g.add(tail);const dorsal=ellipsoid(g,'#ffd079',[-.04,.45,0],[.36,.17,.22],new THREE.ConeGeometry(1,1,4));dorsal.rotation.z=.35;const fin=ellipsoid(g,'#ffb178',[-.05,-.36,.18],[.31,.13,.12],new THREE.ConeGeometry(1,1,4));fin.rotation.z=-.4;
ellipsoid(g,'#fff6db',[.43,.12,.32],[.16,.16,.08],new THREE.IcosahedronGeometry(1,1));ellipsoid(g,'#264e57',[.48,.13,.395],[.075,.085,.045],new THREE.IcosahedronGeometry(1,0));const glint=ellipsoid(g,'#ffffff',[.5,.17,.43],[.025,.028,.018],new THREE.IcosahedronGeometry(1,0));g.scale.setScalar(scale);g.userData.body=body;return g}
const fish=makeFish('#f58a69',1.15);fish.position.set(0,.1,0);scene.add(fish);
// Otters are little faceted shore guardians, each with a soft belly and a fish snack.
const otters=[];const fur=['#aa8064','#cb9b73','#8c725f','#d3a47e'];
function makeOtter(index){const g=new THREE.Group(),c=fur[index%fur.length];ellipsoid(g,c,[0,.02,0],[.46,.65,.38]);ellipsoid(g,'#f3d9b2',[0,-.11,.31],[.29,.43,.12]);ellipsoid(g,c,[0,.61,.02],[.43,.4,.36]);for(const x of [-.31,.31]){ellipsoid(g,c,[x,.91,0],[.17,.17,.13],new THREE.IcosahedronGeometry(1,0));ellipsoid(g,'#edb6a5',[x,.91,.11],[.09,.09,.045],new THREE.IcosahedronGeometry(1,0));ellipsoid(g,'#fff3d8',[x*.62,.62,.34],[.12,.14,.08],new THREE.IcosahedronGeometry(1,0));ellipsoid(g,'#294c51',[x*.62,.62,.405],[.055,.075,.035],new THREE.IcosahedronGeometry(1,0))}ellipsoid(g,'#55453d',[0,.48,.43],[.095,.065,.06],new THREE.IcosahedronGeometry(1,0));ellipsoid(g,'#f1a294',[0,.40,.45],[.06,.035,.025],new THREE.IcosahedronGeometry(1,0));for(const x of [-.23,.23])ellipsoid(g,c,[x,-.22,.28],[.15,.12,.14]);ellipsoid(g,c,[0,-.35,-.3],[.17,.2,.3]);const snack=makeFish('#ffc66b',.18);snack.position.set(.03,-.08,.46);g.add(snack);g.position.y=-.7;g.userData.phase=Math.random()*6;scene.add(g);otters.push(g);return g}
function addOtter(){if(otters.length>=12)return;const i=otters.length,a=(i*2.399)+.4,r=7.15;const o=makeOtter(i);o.position.x=Math.cos(a)*r;o.position.z=Math.sin(a)*r*.73;o.rotation.y=-a+.7}
for(let i=0;i<Math.min(12,Object.values(game.counts).reduce((a,b)=>a+b,0));i++)addOtter();
const raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2();let clickBoost=0;
function catchFish(event){const rect=renderer.domElement.getBoundingClientRect();pointer.x=(event.clientX-rect.left)/rect.width*2-1;pointer.y=-((event.clientY-rect.top)/rect.height)*2+1;raycaster.setFromCamera(pointer,camera);if(raycaster.intersectObject(fish,true).length){game.fish+=power();game.total+=power();clickBoost=1;ring.classList.remove('pop');void ring.offsetWidth;ring.classList.add('pop');message('+'+power()+' fish!');ui();saveGame();for(let i=0;i<4;i++)spawnSpark(event.clientX,event.clientY)} }
renderer.domElement.addEventListener('pointerdown',catchFish);
const sparks=[];function spawnSpark(x,y){const el=document.createElement('span');el.textContent=['✦','🐟','✧'][Math.floor(Math.random()*3)];el.style.cssText=`position:fixed;left:${x}px;top:${y}px;z-index:5;pointer-events:none;color:#fff4b6;font-size:${14+Math.random()*12}px;font-weight:bold;text-shadow:0 2px 6px #327c78;transition:transform .65s ease-out,opacity .65s;`;document.body.appendChild(el);requestAnimationFrame(()=>{el.style.transform=`translate(${Math.random()*90-45}px,${-40-Math.random()*55}px) rotate(${Math.random()*80-40}deg)`;el.style.opacity=0});setTimeout(()=>el.remove(),700)}

