const defs=[{id:'pup',name:'Baby otter',icon:'🦦',cost:18,rate:1.2,desc:'A tiny fish finder'},{id:'buddy',name:'Otter buddies',icon:'🦦',cost:110,rate:6,desc:'Double the splashing'},{id:'family',name:'Otter family',icon:'🦦',cost:620,rate:32,desc:'A whole happy raft'},{id:'net',name:'Shiny net',icon:'✨',cost:55,click:2,desc:'More fish per tap'}];
let save;try{save=JSON.parse(localStorage.pondPals||'{}')}catch{save={}};
const game={fish:Math.max(0,save.fish||0),total:Math.max(0,save.total||0),counts:Object.assign({pup:0,buddy:0,family:0,net:0},save.counts||{}),tap:1};
function rate(){return defs.reduce((n,d)=>n+(d.rate||0)*game.counts[d.id],0)}function power(){return 1+game.counts.net*2}function helperCount(){return game.counts.pup+game.counts.buddy+game.counts.family}
function compact(n){if(n<1000)return Math.floor(n).toLocaleString();const units=['K','M','B','T'];let i=-1;do{n/=1000;i++}while(n>=1000&&i<units.length-1);return n.toFixed(n<10?1:0)+units[i]}
function saveGame(){try{localStorage.pondPals=JSON.stringify({fish:game.fish,total:game.total,counts:game.counts})}catch{}}
function ui(){fishLabel.textContent=compact(game.fish);rateLabel.textContent=compact(rate());totalLabel.textContent=compact(helperCount());for(const d of defs){const btn=document.querySelector('#buy-'+d.id);let price=Math.floor(d.cost*Math.pow(1.16,game.counts[d.id]));btn.querySelector('.price').textContent='🐟 '+compact(price);btn.classList.toggle('afford',game.fish>=price);btn.classList.toggle('locked',game.fish<price);btn.querySelector('.qty').textContent='×'+game.counts[d.id]}}
for(const d of defs){const card=document.createElement('button');card.className='buy-card';card.id='buy-'+d.id;card.innerHTML=`<span class="item-icon">${d.icon}</span><span class="item-info"><b>${d.name}</b><small>${d.desc}</small></span><span class="price">🐟 ${d.cost}</span><span class="qty">×0</span>`;card.addEventListener('click',()=>buy(d));shop.append(card)}
let toastTimer;function message(text){toast.textContent=text;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),1250)}
function buy(d){const price=Math.floor(d.cost*Math.pow(1.16,game.counts[d.id]));if(game.fish<price){message('A few more fish!');return}game.fish-=price;game.counts[d.id]++;if(d.id==='net')message('✨ Shiny net!');else message('🦦 New otter friend!');addOtter();ui();saveGame()}

